#include <list>
#include <stdexcept>

struct ThrowingElement {
    ThrowingElement() { 
        if (rand() % 2 == 0) 
            throw std::runtime_error("Fail construct"); 
    }
};

int main() {
    std::list<int> L = {1, 2};
    size_t initial_size = L.size();
    try {
        // If push_back fails (e.g., bad_alloc or element failure),
        // L.size() will still equal initial_size.
        L.push_back(3);
    } catch (...) {
        // L remains unchanged due to strong guarantee
        // assert(L.size() == initial_size);
    }
}
